// DETECT: turns policies.csv + claims.csv into ranked, evidence-linked signals seen from several points of view.
// Logic written by the team (no AI in the loop): fixed lenses, an automatic dimension x metric scan, and custom detectors.
// Run:  INSURANCE_DATA_DIR=/path node pipeline/detect.mjs        -> pipeline/out/signals.json
import { mkdirSync, writeFileSync } from 'node:fs';
import { P, C, sum, mean, ASOF, quality } from '../analysis/data.mjs';

const OUT = new URL('./out/', import.meta.url); mkdirSync(OUT, { recursive: true });
const log = (m) => console.log(JSON.stringify({ t: new Date().toISOString(), step: 'detect', msg: m }));
const f = (x, d = 2) => (Number.isFinite(x) ? +x.toFixed(d) : null);
const med = (xs) => { const a = xs.slice().sort((x, y) => x - y); return a.length ? a[Math.floor(a.length / 2)] : null; };
const normCdf = (z) => { const t = 1 / (1 + 0.2316419 * Math.abs(z)), d = 0.3989423 * Math.exp((-z * z) / 2), p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274)))); return z > 0 ? 1 - p : p; };
const p2 = (z) => 2 * (1 - normCdf(Math.abs(z))); // two-sided p from z
function rateRatio(a, ea, b, eb) { if (!a || !b || !ea || !eb) return null; const r = a / ea / (b / eb), se = Math.sqrt(1 / a + 1 / b); return { ratio: r, lo: Math.exp(Math.log(r) - 1.96 * se), hi: Math.exp(Math.log(r) + 1.96 * se), z: Math.log(r) / se, p: p2(Math.log(r) / se) }; }
function propTest(x1, n1, x2, n2) { if (!n1 || !n2) return null; const p1 = x1 / n1, q = x2 / n2, pp = (x1 + x2) / (n1 + n2), se = Math.sqrt(pp * (1 - pp) * (1 / n1 + 1 / n2)); const z = se ? (p1 - q) / se : 0; return { p1, p2: q, diff: p1 - q, z, p: p2(z) }; }
function binomTail(k, n, p) { // P(X >= k), normal approx w/ continuity for big n, exact for small
  if (n <= 0) return 1; let s = 0, pm = Math.pow(1 - p, n); for (let i = 0; i < k; i++) { s += pm; pm *= ((n - i) / (i + 1)) * (p / (1 - p)); } return Math.max(0, 1 - s); }
const money = (x) => '$' + Math.round(x).toLocaleString('en-CA');
const pctS = (x, d = 0) => (x * 100).toFixed(d) + '%';

// ---------------------------------------------------------------- base data views
const claims = C, pols = P, T10 = 10000;
const bookExp = sum(pols.map((p) => p.exp)), bookEarned = sum(pols.map((p) => p.earned)), bookInc = sum(claims.map((c) => c.inc));
const bookLR = bookInc / bookEarned, bookFreq = claims.length / bookExp, bookSev = mean(claims.filter((c) => c.amt).map((c) => c.amt));
const written = (ps) => sum(ps.map((p) => p.prem || 0)), paid = (cs) => sum(cs.map((c) => +c.paid_amount || 0));
const closeDays = (cs) => cs.filter((c) => c.closed).map((c) => (c.closed - c.rep) / 864e5);
const claimsOf = (ps) => ps.flatMap((p) => p.cl);
const signals = [];
let seq = 0;
function add(s) { s.id = s.id || 'S' + String(++seq).padStart(2, '0'); signals.push(s); return s; }
const LENS = { FIN: 'Finance (CFO)', PRI: 'Pricing / actuarial', DIS: 'Distribution', OPS: 'Claims operations', RET: 'Retention', FRD: 'Fraud / integrity', SEV: 'Severity / exposure', DQ: 'Data quality' };

// ---------------------------------------------------------------- A. fixed lenses (the six classic views)
log('A. fixed lenses: claims-to-premium by product, city, channel, risk band; claim-type concentration; severe claims');
const ratioPaid = (ps) => paid(claimsOf(ps)) / written(ps);
const byProd = ['Home', 'Auto'].map((t) => { const ps = pols.filter((p) => p.policy_type === t), cs = claimsOf(ps); return { t, paidOverWritten: ratioPaid(ps), lr: sum(cs.map((c) => c.inc)) / sum(ps.map((p) => p.earned)), n: ps.length, claims: cs.length }; });
const H = byProd[0], A = byProd[1];
add({ lens: 'FIN', stakeholders: ['CFO'], issue: 'home-pricing', kind: 'league-table', headline: `Home insurance: claims consume ${pctS(H.paidOverWritten)} of written premium versus ${pctS(A.paidOverWritten)} for Auto.`, metric: { name: 'paid claims ÷ written premium', value: f(H.paidOverWritten, 3), baseline: f(A.paidOverWritten, 3), ratio: f(H.paidOverWritten / A.paidOverWritten, 2) }, exposureView: { name: 'earned loss ratio (incurred proxy ÷ earned premium)', home: f(H.lr, 2), auto: f(A.lr, 2) }, n: H.n, segment: { dimension: 'product', value: 'Home' }, impactUSD: f((H.lr - bookLR) * sum(pols.filter((p) => p.policy_type === 'Home').map((p) => p.earned)), 0), caveats: ['Paid ÷ written ignores unexpired premium and open claims; the earned view is on the same row.'], queries: ['Canada home insurance loss ratio vs auto insurance loss ratio 2025', 'home insurance combined ratio Canada water damage claims'] });

const cityTab = ['Montreal', 'Ottawa', 'Toronto', 'Quebec City', 'Calgary'].map((c) => { const ps = pols.filter((p) => p.city2 === c), cs = claimsOf(ps); return { c, naive: ratioPaid(ps), lr: sum(cs.map((x) => x.inc)) / sum(ps.map((p) => p.earned)), n: ps.length }; }).sort((a, b) => b.naive - a.naive);
add({ lens: 'PRI', stakeholders: ['CFO', 'VP Claims'], issue: 'mtl-water', kind: 'league-table', headline: `Regional pricing: ${cityTab[0].c} (${pctS(cityTab[0].naive)}) and ${cityTab[1].c} (${pctS(cityTab[1].naive)}) have the highest claims-to-premium ratios; ${cityTab[4].c} is lowest (${pctS(cityTab[4].naive)}).`, metric: { name: 'paid claims ÷ written premium', value: f(cityTab[0].naive, 3), baseline: f(ratioPaid(pols), 3), ratio: f(cityTab[0].naive / ratioPaid(pols), 2) }, table: cityTab.map((r) => ({ city: r.c, paidOverWritten: f(r.naive, 3), earnedLR: f(r.lr, 2), policies: r.n })), n: cityTab[0].n, segment: { dimension: 'city', value: cityTab[0].c }, caveats: ['City totals mix products: the cause sits in Home water (see the Montréal signals).'], queries: ['Montreal home insurance water damage claims higher than Toronto', 'Ottawa home insurance claims 2026 storm'] });

const chTab = ['Broker', 'Online', 'Agent'].map((c) => { const ps = pols.filter((p) => p.channel === c), cs = claimsOf(ps); return { c, naive: ratioPaid(ps), lr: sum(cs.map((x) => x.inc)) / sum(ps.map((p) => p.earned)), n: ps.length }; });
const chNoB07 = ['Broker', 'Online', 'Agent'].map((c) => { const ps = pols.filter((p) => p.channel === c && p.broker_code !== 'B07'); return { c, naive: ratioPaid(ps) }; });
add({ lens: 'DIS', stakeholders: ['Head of Distribution', 'CFO'], issue: 'broker-channel', kind: 'league-table', headline: `Distribution channel: broker policies cost ${pctS(chTab[0].naive, 1)} of premium in paid claims versus ${pctS(chTab[1].naive)} Online and ${pctS(chTab[2].naive)} Agent. Without broker B07 the broker figure is ${pctS(chNoB07[0].naive)}.`, metric: { name: 'paid claims ÷ written premium', value: f(chTab[0].naive, 3), baseline: f((chTab[1].naive + chTab[2].naive) / 2, 3), ratio: f(chTab[0].naive / ((chTab[1].naive + chTab[2].naive) / 2), 2) }, table: chTab.map((r) => ({ channel: r.c, paidOverWritten: f(r.naive, 3), earnedLR: f(r.lr, 2), policies: r.n, paidOverWrittenExB07: f(chNoB07.find((x) => x.c === r.c).naive, 3) })), n: chTab[0].n, segment: { dimension: 'channel', value: 'Broker' }, caveats: ['One broker (B07) explains most of the gap; blaming the whole channel would be wrong.'], queries: ['broker vs direct channel loss ratio Canadian personal lines', 'insurance broker oversight loss ratio trigger binding authority'] });

const rk = ['Low', 'Medium', 'High'].map((r) => { const ps = pols.filter((p) => p.risk_band === r), ps2 = ps.filter((p) => p.policy_type === 'Home'); return { r, naive: ratioPaid(ps), lr: sum(claimsOf(ps).map((c) => c.inc)) / sum(ps.map((p) => p.earned)), homeLR: sum(claimsOf(ps2).filter(() => true).map((c) => c.inc)) / sum(ps2.map((p) => p.earned)), homeN: ps2.length }; });
const homeNoB = pols.filter((p) => p.policy_type === 'Home' && p.broker_code !== 'B07');
const homeBand = ['Low', 'Medium', 'High'].map((r) => { const ps = homeNoB.filter((p) => p.risk_band === r); return { r, lr: sum(claimsOf(ps).map((c) => c.inc)) / sum(ps.map((p) => p.earned)), prem: mean(ps.filter((p) => p.prem > 0).map((p) => p.prem)), freq: claimsOf(ps).length / sum(ps.map((p) => p.exp)) }; });
add({ lens: 'PRI', stakeholders: ['CFO'], issue: 'home-pricing', kind: 'league-table', headline: `Risk classification: Medium-risk policies cost ${pctS(rk[1].naive)} of premium vs ${pctS(rk[2].naive)} for High-risk (all lines). In Home the Medium band loss ratio is ${f(homeBand[1].lr, 2)} vs ${f(homeBand[2].lr, 2)} for High, so the bands look mis-priced.`, metric: { name: 'paid claims ÷ written premium', value: f(rk[1].naive, 3), baseline: f(rk[2].naive, 3), ratio: f(rk[1].naive / rk[2].naive, 2) }, table: homeBand.map((r) => ({ homeBand: r.r, earnedLR: f(r.lr, 2), avgPremium: f(r.prem, 0), claimsPerPolicyYear: f(r.freq, 3) })), n: homeNoB.length, segment: { dimension: 'risk band (Home)', value: 'Medium' }, caveats: ['Excludes broker B07. Bands are our own classification; Auto bands behave correctly (loss ratios 0.39/0.46/0.51).'], queries: ['insurance risk classification validation loss ratio by tier lift', 'home insurance rating variables water risk tiers Canada'] });

const tp = {}; for (const c of claims) tp[c.claim_type] = (tp[c.claim_type] || 0) + (+c.paid_amount || 0); const totPaid = sum(Object.values(tp));
const topT = Object.entries(tp).sort((a, b) => b[1] - a[1]); const top2 = (topT[0][1] + topT[1][1]) / totPaid;
add({ lens: 'SEV', stakeholders: ['CFO'], issue: 'mtl-water', kind: 'league-table', headline: `Claim-type concentration: ${topT[0][0]} and ${topT[1][0]} account for ${pctS(top2, 1)} of total claims paid.`, metric: { name: 'share of paid claims', value: f(top2, 3), baseline: null, ratio: null }, table: topT.map(([k, v]) => ({ claimType: k, paid: f(v, 0), share: f(v / totPaid, 3) })), n: claims.length, segment: { dimension: 'claim type', value: `${topT[0][0]} + ${topT[1][0]}` }, caveats: ['Theft share is inflated by broker B07 (60 theft claims).'], queries: ['water damage share of home insurance claims Canada', 'auto theft claims Canada cost 2025'] });

const big = claims.filter((c) => c.amt >= T10), bigShare = sum(big.map((c) => c.amt)) / sum(claims.map((c) => c.amt || 0));
const fire = claims.filter((c) => c.claim_type === 'Fire');
add({ lens: 'SEV', stakeholders: ['CFO', 'VP Claims'], issue: 'severe-claims', kind: 'league-table', headline: `Severe claims: ${big.length} claims (${pctS(big.length / claims.length)}) are $10,000 or more and carry ${pctS(bigShare)} of claim dollars; the ${fire.length} Fire claims average ${money(mean(fire.filter((c) => c.amt).map((c) => c.amt)))}.`, metric: { name: 'share of claim dollars in claims ≥ $10k', value: f(bigShare, 3), baseline: f(big.length / claims.length, 3), ratio: f(bigShare / (big.length / claims.length), 2) }, table: Object.entries(big.reduce((m, c) => ((m[c.claim_type] = (m[c.claim_type] || 0) + 1), m), {})).map(([k, v]) => ({ claimType: k, claimsOver10k: v })), n: big.length, segment: { dimension: 'claim size', value: '≥ $10,000' }, caveats: ['Fire has only 13 records: high volatility, low credibility.'], queries: ['large loss concentration property insurance share of losses top 10% claims', 'fire claim average severity Canada insurance'] });

// ---------------------------------------------------------------- B. automatic scan: every dimension x every metric vs the rest of the book
log('B. automatic scan: dimensions x metrics, rate-ratio and proportion tests, ranked by significance x materiality');
const doneRenew = pols.filter((p) => ['Renewed', 'Not Renewed'].includes(p.renewal_status));
const dims = [
  ['product', (p) => p.policy_type], ['city', (p) => p.city2], ['channel', (p) => p.channel], ['broker', (p) => p.broker || '(none)'], ['risk band', (p) => p.risk_band],
  ['deductible', (p) => '$' + p.ded], ['age band', (p) => p.ageBand], ['start half-year', (p) => p.start.getUTCFullYear() + 'H' + (p.start.getUTCMonth() < 6 ? 1 : 2)], ['bundle', (p) => (p.bundle === 'yes' ? 'bundled' : 'single line')],
  ['product × city', (p) => p.policy_type + ' · ' + p.city2],
];
const cand = [];
for (const [dname, key] of dims) {
  const groups = new Map(); for (const p of pols) { const k = key(p); if (!groups.has(k)) groups.set(k, []); groups.get(k).push(p); }
  for (const [seg, ps] of groups) {
    if (ps.length < 40) continue;
    const rest = pols.filter((p) => key(p) !== seg), cs = claimsOf(ps), rcs = claimsOf(rest), ex = sum(ps.map((p) => p.exp)), rex = sum(rest.map((p) => p.exp));
    const ep = sum(ps.map((p) => p.earned)), inc = sum(cs.map((c) => c.inc)), restLR = sum(rcs.map((c) => c.inc)) / sum(rest.map((p) => p.earned));
    const fr = rateRatio(cs.length, ex, rcs.length, rex);
    if (fr && cs.length >= 15 && Math.abs(fr.z) >= 3.5) cand.push({ dname, seg, metric: 'claim frequency per policy-year', value: cs.length / ex, base: rcs.length / rex, ratio: fr.ratio, ci: [fr.lo, fr.hi], p: fr.p, z: fr.z, n: ps.length, impact: (cs.length / ex - rcs.length / rex) * ex * (mean(cs.map((c) => c.inc)) || 0) });
    const lr = inc / ep; if (cs.length >= 20 && ps.length >= 80 && Math.abs(lr / restLR - 1) >= 0.35 && Math.abs(inc - restLR * ep) > 60000) { // LR materiality screen (z from frequency+severity noise approximated by claim count)
      const se = 1 / Math.sqrt(cs.length) * 1.2; const z = Math.log(lr / restLR) / se; if (Math.abs(z) >= 3.5) cand.push({ dname, seg, metric: 'earned loss ratio', value: lr, base: restLR, ratio: lr / restLR, ci: [lr / restLR * Math.exp(-1.96 * se), lr / restLR * Math.exp(1.96 * se)], p: p2(z), z, n: ps.length, impact: inc - restLR * ep }); }
    const early = cs.filter((c) => c.dayIn <= 45).length, rearly = rcs.filter((c) => c.dayIn <= 45).length, pt = propTest(early, cs.length, rearly, rcs.length);
    if (pt && cs.length >= 20 && Math.abs(pt.z) >= 4) cand.push({ dname, seg, metric: 'share of claims within 45 days of policy start', value: pt.p1, base: pt.p2, ratio: pt.p1 / pt.p2, ci: null, p: pt.p, z: pt.z, n: cs.length, impact: null });
    const dn = cs.filter((c) => c.status === 'Denied').length, rdn = rcs.filter((c) => c.status === 'Denied').length, pd = propTest(dn, cs.length, rdn, rcs.length);
    if (pd && cs.length >= 30 && Math.abs(pd.z) >= 3.2) cand.push({ dname, seg, metric: 'denial rate', value: pd.p1, base: pd.p2, ratio: pd.p1 / pd.p2, ci: null, p: pd.p, z: pd.z, n: cs.length, impact: null });
    const bg = cs.filter((c) => c.amt >= T10).length, rbg = rcs.filter((c) => c.amt >= T10).length, pb = propTest(bg, cs.length, rbg, rcs.length);
    if (pb && cs.length >= 30 && Math.abs(pb.z) >= 3.5) cand.push({ dname, seg, metric: 'share of claims ≥ $10k (senior review)', value: pb.p1, base: pb.p2, ratio: pb.p1 / pb.p2, ci: null, p: pb.p, z: pb.z, n: cs.length, impact: null });
    const ps2 = ps.filter((p) => ['Renewed', 'Not Renewed'].includes(p.renewal_status)), rps = doneRenew.filter((p) => key(p) !== seg), nr = propTest(ps2.filter((p) => p.renewal_status === 'Not Renewed').length, ps2.length, rps.filter((p) => p.renewal_status === 'Not Renewed').length, rps.length);
    if (nr && ps2.length >= 80 && Math.abs(nr.z) >= 3) cand.push({ dname, seg, metric: 'non-renewal rate', value: nr.p1, base: nr.p2, ratio: nr.p1 / nr.p2, ci: null, p: nr.p, z: nr.z, n: ps2.length, impact: null });
    const cd = closeDays(cs), rcd = closeDays(rcs); if (cd.length >= 40) { const m1 = med(cd), m2 = med(rcd); if (m1 && m2 && Math.abs(m1 / m2 - 1) >= 0.25) { // bootstrap CI for median diff
      let ge = 0; const B = 400; for (let b = 0; b < B; b++) { const s1 = Array.from({ length: cd.length }, () => cd[Math.floor(Math.random() * cd.length)]), s2 = Array.from({ length: rcd.length }, () => rcd[Math.floor(Math.random() * rcd.length)]); if (med(s1) <= med(s2)) ge++; }
      const pb2 = Math.min(1, 2 * Math.min(ge, B - ge) / B); if (pb2 < 0.005) cand.push({ dname, seg, metric: 'median days from report to close', value: m1, base: m2, ratio: m1 / m2, ci: null, p: pb2, z: null, n: cd.length, impact: null }); } }
  }
}
// claim-level dimensions
for (const [dname, key] of [['claim type', (c) => c.claim_type], ['adjuster team', (c) => c.adjuster_team], ['claim status', (c) => c.status]]) {
  const groups = new Map(); for (const c of claims) { const k = key(c); if (!groups.has(k)) groups.set(k, []); groups.get(k).push(c); }
  for (const [seg, cs] of groups) { if (cs.length < 30) continue; const rcs = claims.filter((c) => key(c) !== seg);
    const cd = closeDays(cs), rcd = closeDays(rcs); if (cd.length >= 40 && med(rcd)) { const m1 = med(cd), m2 = med(rcd); if (Math.abs(m1 / m2 - 1) >= 0.25) cand.push({ dname, seg, metric: 'median days from report to close', value: m1, base: m2, ratio: m1 / m2, ci: null, p: 0.001, z: null, n: cd.length, impact: null }); }
    const bg = cs.filter((c) => c.amt >= T10).length, rbg = rcs.filter((c) => c.amt >= T10).length, pb = propTest(bg, cs.length, rbg, rcs.length); if (pb && Math.abs(pb.z) >= 3.5) cand.push({ dname, seg, metric: 'share of claims ≥ $10k (senior review)', value: pb.p1, base: pb.p2, ratio: pb.p1 / pb.p2, ci: null, p: pb.p, z: pb.z, n: cs.length, impact: null });
    const am = mean(cs.filter((c) => c.amt).map((c) => c.amt)), ram = mean(rcs.filter((c) => c.amt).map((c) => c.amt)); if (Math.abs(am / ram - 1) >= 0.4 && cs.length >= 40) cand.push({ dname, seg, metric: 'mean claim amount', value: am, base: ram, ratio: am / ram, ci: null, p: 0.001, z: null, n: cs.length, impact: null });
  } }
// issue router: which business issue does a scan finding belong to
const routeIssue = (c) => {
  const s = (c.dname + ' ' + c.seg + ' ' + c.metric).toLowerCase();
  if (s.includes('b07') || (/start half-year/.test(s) && /2026/.test(s))) return 'b07-fraud';
  if (/bundle/.test(s)) return 'bundle-opportunity';
  if (/(montreal|quebec city)/.test(s) && /home|water|frequency|loss ratio/.test(s)) return 'mtl-water';
  if (/adjuster team|team c|median days|senior|≥ \$10k/.test(s)) return 'senior-review';
  if (/non-renewal/.test(s)) return 'claim-wait-retention';
  if (/risk band|deductible|product/.test(s)) return 'home-pricing';
  if (/channel|broker/.test(s)) return 'broker-channel';
  if (/claim type|fire|mean claim/.test(s)) return 'severe-claims';
  return 'other';
};
const lensOf = (c) => /denial|median days|adjuster|status/.test(c.metric + c.dname) ? 'OPS' : /non-renewal/.test(c.metric) ? 'RET' : /45 days/.test(c.metric) ? 'FRD' : /broker|channel/.test(c.dname) ? 'DIS' : /≥ \$10k|mean claim/.test(c.metric) ? 'SEV' : /loss ratio|frequency/.test(c.metric) ? 'PRI' : 'FIN';
for (const c of cand) c.score = Math.min(60, Math.abs(c.z ?? 4)) * (1 + Math.log10(1 + Math.abs(c.impact || 0) / 10000));
cand.sort((a, b) => b.score - a.score);
const seen = new Set();
for (const c of cand) { // keep the strongest few per issue + metric to avoid a wall of near-duplicates
  const issue = routeIssue(c), key = issue + '|' + c.metric + '|' + c.dname; if (seen.has(key + c.seg)) continue; seen.add(key + c.seg);
  const per = signals.filter((s) => s.kind === 'scan' && s.issue === issue).length; if (per >= 6) continue;
  const dirUp = c.ratio >= 1; const un = /rate|share|ratio/.test(c.metric);
  const fmtv = (v) => (c.metric.startsWith('median days') ? f(v, 0) + ' days' : /amount/.test(c.metric) ? money(v) : /frequency/.test(c.metric) ? f(v, 3) + ' per policy-year' : /loss ratio/.test(c.metric) ? f(v, 2) : pctS(v, 1));
  add({ lens: lensOf(c), stakeholders: [], issue, kind: 'scan', headline: `${c.dname} = ${c.seg}: ${c.metric} is ${fmtv(c.value)} versus ${fmtv(c.base)} for the rest of the book (×${f(c.ratio, 2)}).`, metric: { name: c.metric, value: f(c.value, 4), baseline: f(c.base, 4), ratio: f(c.ratio, 2) }, stats: { test: /frequency/.test(c.metric) ? 'Poisson rate ratio (exposure offset)' : /(share|rate)/.test(c.metric) ? 'two-proportion z-test' : 'screen + bootstrap', ci95: c.ci ? [f(c.ci[0], 2), f(c.ci[1], 2)] : null, p: c.p < 1e-12 ? '<1e-12' : +c.p.toPrecision(2), z: c.z ? f(c.z, 1) : null }, n: c.n, segment: { dimension: c.dname, value: c.seg }, impactUSD: c.impact ? f(c.impact, 0) : null, caveats: [dirUp ? 'Association in one book, not proof of cause.' : 'Favourable gap: check it is not a survivorship effect.'], queries: [] });
}
log(`B. scan produced ${signals.filter((s) => s.kind === 'scan').length} ranked findings from ${cand.length} significant candidates`);

// ---------------------------------------------------------------- C. custom detectors (logic we can defend line by line)
log('C1. early-claim and threshold-structuring detectors by broker');
const brokers = [...new Set(pols.map((p) => p.broker).filter(Boolean))].sort();
const bookEarly = claims.filter((c) => c.dayIn <= 45).length / claims.length;
const nearBand = (c) => c.amt >= 0.8 * T10 && c.amt < T10; const bookNear = claims.filter(nearBand).length / claims.length;
const brokerRows = brokers.map((b) => { const ps = pols.filter((p) => p.broker === b), cs = claimsOf(ps); const early = cs.filter((c) => c.dayIn <= 45).length, near = cs.filter(nearBand).length, theft = cs.filter((c) => c.claim_type === 'Theft').length; const lr = sum(cs.map((c) => c.inc)) / sum(ps.map((p) => p.earned));
  return { broker: b, policies: ps.length, claims: cs.length, earlyShare: cs.length ? early / cs.length : 0, nearShare: cs.length ? near / cs.length : 0, theftShare: cs.length ? theft / cs.length : 0, lr, pEarly: binomTail(early, cs.length, bookEarly), pNear: binomTail(near, cs.length, bookNear), medianDaysToLoss: med(cs.map((c) => c.dayIn)), denied: cs.filter((c) => c.status === 'Denied').length, firstStart: ps.map((p) => p.start).sort((a, b) => a - b)[0]?.toISOString().slice(0, 10), mean: mean(cs.filter((c) => c.claim_type === 'Theft' && c.amt).map((c) => c.amt)) }; });
