  'home-bands': S('home-bands', 'Home vs Auto: losses by risk band', 'groupbars', 'loss ratio', [{ name: 'Home', points: homeBand.map((r) => ({ x: r.r, y: f(r.lr, 2) })) }, { name: 'Auto', points: ['Low', 'Medium', 'High'].map((r) => { const ps = pols.filter((p) => p.policy_type === 'Auto' && p.broker_code !== 'B07' && p.risk_band === r); return { x: r, y: f(sum(claimsOf(ps).map((c) => c.inc)) / sum(ps.map((p) => p.earned)), 2) }; }) }], 'In Auto, riskier bands cost more, as they should. In Home, the "Medium" band costs more than "High".', 'Earned loss ratio = estimated claim cost ÷ earned premium, by risk_band, excluding broker B07.', { ref: 1 }),
